#include "scarlett_imports64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m; ScarlettImports64 i; assert(i.install(m)); using F=GuestMemory64::Fault; assert(m.map(0x1000,4096,3)==F::none); uint64_t r=0; auto call=[&](const char*d,const char*n,uint64_t a=0,uint64_t b=0,uint64_t c=0,uint64_t e=0){auto f=i.registerImport(d,n);assert(f);assert(i.dispatch(f,m,a,r,b,c,e));return r;}; const char* mem="api-ms-win-core-memory-l1-1-0.dll"; auto a=call(mem,"VirtualAlloc",0,8192,0x3000,4);assert(a&&m.check(a,8192,3)==F::none);assert(call(mem,"VirtualFree",a,0,0x8000)==1);assert(m.check(a,1,0)==F::unmapped);assert(call(mem,"VirtualFree",a,0,0x8000)==0);assert(m.write(0x1000,std::array<uint8_t,6>{'a','b','c','b','c',0})==F::none);assert(m.write(0x1100,std::array<uint8_t,3>{'b','c',0})==F::none);assert(call("VCRUNTIME140.dll","strstr",0x1000,0x1100)==0x1001);const char* str="api-ms-win-crt-string-l1-1-0.dll";assert(call(str,"strcpy_s",0x1200,8,0x1100)==0);assert(call(str,"strcat_s",0x1200,8,0x1100)==0);std::array<uint8_t,5>b{};assert(m.read(0x1200,b)==F::none);assert((b==std::array<uint8_t,5>{'b','c','b','c',0}));assert(call(str,"strcpy_s",0x1200,2,0x1100)==34);assert(call(str,"strncpy_s",0x1200,2,0x1100,UINT64_MAX)==80);assert(call("api-ms-win-core-processthreads-l1-1-0.dll","GetProcessId",UINT64_MAX)==1000);std::cout<<"V33 tests passed\n";}
